17. export interface CartTotals {
18.   subtotalCents: number;
19.   discountCents: number;
20.   taxCents: number;
21.   shippingCents: number;
22.   totalCents: number;
23. }
24. 
25. export interface CartConfig {
26.   discountPolicy?: DiscountPolicy;
27.   taxCalculator?: TaxCalculator;
28.   shippingCalculator?: ShippingCalculator;
29.   /** ISO region used for tax look-ups. Defaults to "US". */
30.   region?: string;
31. }
32. 
33. export interface CheckoutCollaborators {
34.   priceFetcher?: PriceFetcher;
35.   inventoryChecker?: InventoryChecker;
36.   asyncTaxProvider?: AsyncTaxRateProvider;
37. }
38. 
39. export interface CheckoutResult {
40.   totals: CartTotals;
41.   lines: readonly CartLine[];
42. }
43. 
44. /**
45.  * Cart aggregates lines of products and computes totals. The pricing pipeline
46.  * is fixed at: **subtotal → discount (clamped to [0, subtotal]) → tax on the
47.  * discounted subtotal → shipping (computed against discounted subtotal)**.
48.  *
49.  * The cart never reaches the network or filesystem itself; all I/O is delegated
50.  * to injected collaborators (DiscountPolicy / TaxCalculator / ShippingCalculator
51.  * for sync totals, and PriceFetcher / InventoryChecker / AsyncTaxRateProvider
52.  * for `checkout()`).
53.  */
54. export class Cart {
55.   private readonly lines = new Map<string, CartLine>();
56.   private readonly discountPolicy: DiscountPolicy;
57.   private readonly taxCalculator: TaxCalculator;
58.   private readonly shippingCalculator: ShippingCalculator;
59.   private readonly region: string;
60. 
61.   constructor(config: CartConfig = {}) {
62.     this.discountPolicy = config.discountPolicy ?? new NoDiscountPolicy();
63.     this.taxCalculator = config.taxCalculator ?? new NoTaxCalculator();
64.     this.shippingCalculator =
65.       config.shippingCalculator ?? new FreeShippingCalculator();
66.     this.region = config.region ?? "US";
67.   }
68. 
69.   add(product: Product, quantity: number): void {
70.     if (!Number.isInteger(quantity) || quantity <= 0) {
71.       throw new RangeError(`quantity must be a positive integer (got ${quantity})`);
72.     }
73.     if (product.unitPriceCents < 0) {
74.       throw new RangeError(`unitPriceCents must be non-negative (got ${product.unitPriceCents})`);
75.     }
76. 
77.     const existing = this.lines.get(product.id);
78.     if (existing) {
79.       existing.quantity += quantity;
80.     } else {
81.       this.lines.set(product.id, { product, quantity });
82.     }
83.   }
84. 
85.   remove(productId: string): boolean {
86.     return this.lines.delete(productId);
87.   }
88. 
89.   updateQuantity(productId: string, quantity: number): void {
90.     if (!Number.isInteger(quantity) || quantity < 0) {
91.       throw new RangeError(`quantity must be a non-negative integer (got ${quantity})`);
92.     }
93.     const line = this.lines.get(productId);
94.     if (!line) {
95.       throw new Error(`Product ${productId} is not in the cart`);
96.     }
97.     if (quantity === 0) {
98.       this.lines.delete(productId);
99.       return;
100.     }
101.     line.quantity = quantity;
102.   }
103. 
104.   clear(): void {
105.     this.lines.clear();
106.   }
107. 
108.   get itemCount(): number {
109.     let total = 0;
110.     for (const line of this.lines.values()) total += line.quantity;
111.     return total;
112.   }
113. 
114.   totals(): CartTotals {
115.     return this.computeTotals(this.snapshot());
116.   }
117. 
118.   snapshot(): readonly CartLine[] {
119.     // Deep-copy both the CartLine and its Product so callers mutating the
120.     // returned snapshot cannot reach back into the cart's internal state.
121.     return Array.from(this.lines.values()).map((line) => ({
122.       product: { ...line.product },
123.       quantity: line.quantity,
124.     }));
125.   }
126. 
127.   /**
128.    * Async checkout pipeline:
129.    *  1. Refresh prices via the (optional) `priceFetcher`.
130.    *  2. Validate inventory via the (optional) `inventoryChecker`; first denial
131.    *     wins and throws an :class:`InventoryError` describing the failing line.
132.    *  3. Compute totals; if an `asyncTaxProvider` is supplied, the tax calculator
133.    *     is replaced for this call by an :class:`AsyncTaxCalculator`.
134.    */
135.   async checkout(collaborators: CheckoutCollaborators = {}): Promise<CheckoutResult> {
136.     let lines = this.snapshot();
137.     if (collaborators.priceFetcher) {
138.       lines = await refreshPrices(lines, collaborators.priceFetcher);
139.     }
140.     if (collaborators.inventoryChecker) {
141.       for (const line of lines) {
142.         const decision = await collaborators.inventoryChecker.check(
143.           line.product.id,
144.           line.quantity,
145.         );
146.         const available = decision.availableQuantity;
147.         if (!decision.available || (available !== undefined && available < line.quantity)) {
148.           throw new InventoryError(
149.             decision.reason ??
150.               `insufficient stock for ${line.product.id}: requested ${line.quantity}, available ${available ?? 0}`,
151.             line.product.id,
152.             line.quantity,
153.             available,
154.           );
155.         }
156.       }
157.     }
158.     const totals = collaborators.asyncTaxProvider
159.       ? await this.computeTotalsAsync(lines, collaborators.asyncTaxProvider)
160.       : this.computeTotals(lines);
161.     return { totals, lines };
162.   }
163. 
164.   private computeSubtotal(lines: readonly CartLine[]): number {
165.     let total = 0;
166.     for (const line of lines) {
167.       total += line.product.unitPriceCents * line.quantity;
168.     }
169.     return total;
170.   }
171. 
172.   private clampDiscount(subtotalCents: number): number {
173.     return Math.min(
174.       Math.max(0, this.discountPolicy.computeDiscountCents(subtotalCents)),
175.       subtotalCents,
176.     );
177.   }
178. 
179.   private computeTotals(lines: readonly CartLine[]): CartTotals {
180.     const subtotalCents = this.computeSubtotal(lines);
181.     const discountCents = this.clampDiscount(subtotalCents);
182.     const discountedSubtotal = subtotalCents - discountCents;
183.     const taxCents = Math.max(
184.       0,
185.       this.taxCalculator.computeTaxCents(discountedSubtotal, this.region),
186.     );
187.     const shippingCents = Math.max(
188.       0,
189.       this.shippingCalculator.computeShippingCents(lines, discountedSubtotal),
190.     );
191.     return {
192.       subtotalCents,
193.       discountCents,
194.       taxCents,
195.       shippingCents,
196.       totalCents: discountedSubtotal + taxCents + shippingCents,
197.     };
198.   }
199. 
200.   private async computeTotalsAsync(
201.     lines: readonly CartLine[],
202.     provider: AsyncTaxRateProvider,
203.   ): Promise<CartTotals> {
204.     const subtotalCents = this.computeSubtotal(lines);
205.     const discountCents = this.clampDiscount(subtotalCents);
206.     const discountedSubtotal = subtotalCents - discountCents;
207.     const asyncTax = new AsyncTaxCalculator(provider);
208.     const taxCents = Math.max(
209.       0,
210.       await asyncTax.computeTaxCents(discountedSubtotal, this.region),
211.     );
212.     const shippingCents = Math.max(
213.       0,
214.       this.shippingCalculator.computeShippingCents(lines, discountedSubtotal),
215.     );
216.     return {
217.       subtotalCents,
218.       discountCents,
219.       taxCents,
220.       shippingCents,
221.       totalCents: discountedSubtotal + taxCents + shippingCents,
222.     };
223.   }
224. }
