import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [999999, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "percent must be between 0 and 100"],
      [101, "percent must be between 0 and 100"],
      [NaN, "percent must be between 0 and 100"],
      [Infinity, "percent must be between 0 and 100"],
    ])("rejects invalid percent %s", (percent, msg) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(msg);
    });

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [10, 1000, 100],
      [25, 999, 249],    // floors: 999*25/100 = 249.75 → 249
      [50, 1, 0],        // 1*50/100 = 0.5 → 0 (floor)
      [100, 5000, 5000],
      [0, 5000, 0],
    ])("%i%% of %i cents = %i", (percent, subtotal, expected) => {
      const policy = new PercentageDiscountPolicy(percent);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "non-negative integer"],
      [10.5, "non-negative integer"],
      [NaN, "non-negative integer"],
    ])("rejects invalid amountCents %s", (amount, msg) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(msg);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [500, 1000, 500],   // discount < subtotal
      [500, 300, 300],    // discount > subtotal → clamped to subtotal
      [500, 500, 500],    // discount === subtotal
      [500, 0, 0],        // zero subtotal
      [500, -100, 0],     // negative subtotal
      [0, 1000, 0],       // zero discount
    ])("fixed %i on subtotal %i = %i", (amount, subtotal, expected) => {
      const policy = new FixedAmountDiscountPolicy(amount);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies on original subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed 200 → sum = 300
      expect(policy.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const policy = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum",
      );
      // Both policies individually clamped to subtotal (1000), so 1000 + 1000 = 2000
      // Wait: FixedAmountDiscountPolicy clamps to min(amount, subtotal) = min(600, 1000) = 600 each
      expect(policy.computeDiscountCents(1000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 1000 = 100, remaining = 900
      // Second: 10% of 900 = 90, remaining = 810
      // Total discount = 190
      expect(policy.computeDiscountCents(1000)).toBe(190);
    });

    it("ordering matters in chain mode", () => {
      const bigFirst = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const smallFirst = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // bigFirst: fixed 500 on 1000 → remaining 500, then 50% of 500 = 250. Total = 750
      // smallFirst: 50% of 1000 = 500 → remaining 500, then fixed min(500, 500) = 500. Total = 1000
      expect(bigFirst.computeDiscountCents(1000)).toBe(750);
      expect(smallFirst.computeDiscountCents(1000)).toBe(1000);
    });

    it("chain cannot exceed subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // First: min(800, 1000) = 800, remaining = 200
      // Second: min(800, 200) = 200, remaining = 0
      // Total = 1000
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });
  });

  describe("defaults to sum mode", () => {
    it("uses sum mode when mode is not specified", () => {
      const policy = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      // sum: both on 1000 → 100 + 200 = 300
      expect(policy.computeDiscountCents(1000)).toBe(300);
    });
  });
});

