import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product, CartLine } from "../src/product.ts";

const product = (
  id: string,
  unitPriceCents: number,
  weightGrams?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
  weightGrams,
});

describe("Cart - line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  describe("add", () => {
    it("adds a new product", () => {
      cart.add(product("a", 1000), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity for duplicate product", () => {
      cart.add(product("a", 1000), 2);
      cart.add(product("a", 1000), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
      expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes existing product and returns true", () => {
      cart.add(product("a", 1000), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product", () => {
      expect(cart.remove("unknown")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      cart.add(product("a", 1000), 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      cart.add(product("a", 1000), 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      expect(() => cart.updateQuantity("unknown", 5)).toThrow(
        "Product unknown is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      cart.add(product("a", 1000), 2);
      cart.add(product("b", 500), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns deep copy of lines", () => {
      cart.add(product("a", 1000), 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0]!.product.id).toBe("a");
      expect(snap[0]!.quantity).toBe(2);
    });

    it("mutations to snapshot do not affect cart", () => {
      cart.add(product("a", 1000), 2);
      const snap = cart.snapshot() as CartLine[];
      snap[0]!.quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });
});

describe("Cart - pricing pipeline (totals)", () => {
  it("computes subtotal as sum of (price * qty)", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 3);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(3500); // 2000 + 1500
  });

  it("applies discount from injected policy", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 2000), 1);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(2000);
    expect(totals.discountCents).toBe(500);
    expect(discount.computeDiscountCents).toHaveBeenCalledWith(2000);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(1000);

    const negDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart2 = new Cart({ discountPolicy: negDiscount });
    cart2.add(product("a", 1000), 1);
    expect(cart2.totals().discountCents).toBe(0);
  });

  it("computes tax on discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax, region: "FR" });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // discounted subtotal = 1000 - 200 = 800
    expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "FR");
    expect(totals.taxCents).toBe(80);
  });

  it("passes lines and discounted subtotal to shipping calculator", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // discounted subtotal = 1000 - 300 = 700
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      700,
    );
    expect(totals.shippingCents).toBe(500);
  });

  it("computes totalCents = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(50),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // discountedSubtotal = 1000 - 100 = 900
    // total = 900 + 50 + 200 = 1150
    expect(totals.totalCents).toBe(1150);
  });

  it("returns zeros for empty cart", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("defaults to US region", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 100), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(100, "US");
  });
});

describe("Cart - async checkout()", () => {
  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    expect(result.totals.subtotalCents).toBe(1500);
  });

  it("checks inventory and passes for available items", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 0,
        reason: "sold out",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(2);
      expect(err.available).toBe(0);
      expect(err.message).toBe("sold out");
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(product("a", 1000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal=1000, discount=200, discountedSubtotal=800
    // tax = floor(800 * 0.1) = 80
    // shipping = 300
    // total = 800 + 80 + 300 = 1180
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    expect(result.totals.taxCents).toBe(80);
    expect(result.totals.totalCents).toBe(1180);
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart({ region: "FR" });
    cart.add(product("a", 500), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(600),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2),
    };
    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });
    // refreshed price: 600 * 2 = 1200 subtotal
    // no discount policy → discount = 0
    // tax = floor(1200 * 0.2) = 240
    // no shipping → 0
    // total = 1200 + 240 + 0 = 1440
    expect(result.totals.subtotalCents).toBe(1200);
    expect(result.totals.taxCents).toBe(240);
    expect(result.totals.totalCents).toBe(1440);
  });

  it("works without any collaborators", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.totalCents).toBe(1000);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("network error")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("network error");
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });
});

